<?php require_once 'includes/db.php'; session_start(); require_once 'includes/functions.php'; $map=['produto'=>'produtos','endereco'=>'enderecos','transportador'=>'transportadores']; $tipo=$_GET['tipo']??''; $id=(int)($_GET['id']??0); if(!isset($map[$tipo])||!$id){flash('Solicitação inválida.','danger');redirect('index.php');} try{$s=$pdo->prepare('DELETE FROM '.$map[$tipo].' WHERE id=?');$s->execute([$id]);flash('Registro excluído.');}catch(PDOException $e){flash('Não foi possível excluir: o registro pode estar vinculado a um frete.','danger');} redirect($tipo==='produto'?'produtos.php':($tipo==='endereco'?'enderecos.php':'transportadores.php'));
